public static Namespaces getNamespaces(Element element) {
Assert.isNotNull(element);
Node parent;
parent = element.getParentNode();
for (; parent != null && !isElement(parent);) parent = parent.getParentNode();
Namespaces namespaces;
namespaces = null;
if (parent != null) namespaces = getNamespaces((Element) parent);
return getNamespaces(element, namespaces, false);
}
